import React, { useRef } from 'react';

// ─── Brand tokens ─────────────────────────────────────────────────────────────
const BLUE   = '#009FE3';
const NAVY   = '#003D6B';

// ─── Types ───────────────────────────────────────────────────────────────────

export interface FilterDef {
  /** Unique key used in state maps */
  id: string;
  /** Human-readable label shown on the card */
  label: string;
  /**
   * Must match the ThoughtSpot column name exactly (case-sensitive).
   * Update these to match the Smyths data model.
   */
  columnName: string;
  /** Selectable values — update to match real data values */
  options: string[];
}

export type FilterSelection = Record<string, string[]>;

interface FilterBarProps {
  filters: FilterDef[];
  selected: FilterSelection;
  onSelectionChange: (filterId: string, values: string[]) => void;
  onClearAll: () => void;
  /** True while live values are still being fetched from ThoughtSpot */
  loading?: boolean;
}

// ─── Single filter card ───────────────────────────────────────────────────────

function FilterCard({
  filter,
  selected,
  onChange,
}: {
  filter: FilterDef;
  selected: string[];
  onChange: (values: string[]) => void;
}) {
  const hasSelection = selected.length > 0;
  const listRef = useRef<HTMLDivElement>(null);

  const toggle = (option: string) => {
    if (selected.includes(option)) {
      onChange(selected.filter((v) => v !== option));
    } else {
      onChange([...selected, option]);
    }
  };

  return (
    <div
      style={{
        width: 196,
        flexShrink: 0,
        display: 'flex',
        flexDirection: 'column',
        backgroundColor: '#FFFFFF',
        borderRadius: 10,
        border: `1.5px solid ${hasSelection ? BLUE : 'rgba(0,0,0,0.09)'}`,
        boxShadow: hasSelection
          ? `0 0 0 3px rgba(0,159,227,0.12), 0 2px 8px rgba(0,0,0,0.06)`
          : '0 1px 4px rgba(0,0,0,0.06)',
        overflow: 'hidden',
        transition: 'border-color 0.15s ease, box-shadow 0.15s ease',
      }}
    >
      {/* ── Card header ── */}
      <div
        style={{
          padding: '9px 12px 8px',
          borderBottom: '1px solid rgba(0,0,0,0.07)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          flexShrink: 0,
          background: hasSelection
            ? `linear-gradient(135deg, rgba(0,159,227,0.08) 0%, rgba(0,159,227,0.03) 100%)`
            : '#FAFAFA',
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          {/* Filter funnel icon */}
          <svg
            width="11"
            height="11"
            viewBox="0 0 24 24"
            fill="none"
            stroke={hasSelection ? BLUE : 'rgba(0,0,0,0.35)'}
            strokeWidth="2.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3" />
          </svg>
          <span
            style={{
              fontSize: 12,
              fontWeight: 700,
              color: hasSelection ? BLUE : NAVY,
              letterSpacing: '-0.01em',
            }}
          >
            {filter.label}
          </span>
        </div>

        {hasSelection ? (
          <button
            type="button"
            onClick={() => onChange([])}
            style={{
              background: 'none',
              border: 'none',
              cursor: 'pointer',
              fontSize: 10,
              color: BLUE,
              fontWeight: 700,
              padding: '1px 5px',
              borderRadius: 4,
              letterSpacing: '0.02em',
              lineHeight: 1.4,
            }}
          >
            Clear
          </button>
        ) : (
          <span
            style={{
              fontSize: 10,
              color: 'rgba(0,0,0,0.28)',
              fontWeight: 500,
              letterSpacing: '0.02em',
            }}
          >
            All
          </span>
        )}
      </div>

      {/* ── Scrollable options list ── */}
      <div
        ref={listRef}
        style={{
          overflowY: 'auto',
          maxHeight: 172,
          padding: '3px 0',
          /* Custom scrollbar */
          scrollbarWidth: 'thin',
          scrollbarColor: `rgba(0,159,227,0.3) transparent`,
        }}
      >
        {filter.options.map((option) => {
          const isSelected = selected.includes(option);
          return (
            <label
              key={option}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 8,
                padding: '5px 12px',
                cursor: 'pointer',
                backgroundColor: isSelected
                  ? 'rgba(0,159,227,0.07)'
                  : 'transparent',
                transition: 'background-color 0.10s ease',
                userSelect: 'none',
              }}
              onMouseEnter={(e) => {
                if (!isSelected)
                  (e.currentTarget as HTMLElement).style.backgroundColor =
                    'rgba(0,0,0,0.03)';
              }}
              onMouseLeave={(e) => {
                (e.currentTarget as HTMLElement).style.backgroundColor =
                  isSelected ? 'rgba(0,159,227,0.07)' : 'transparent';
              }}
            >
              {/* Custom checkbox */}
              <span
                style={{
                  width: 15,
                  height: 15,
                  borderRadius: 3,
                  flexShrink: 0,
                  border: `1.5px solid ${isSelected ? BLUE : 'rgba(0,0,0,0.22)'}`,
                  backgroundColor: isSelected ? BLUE : '#FFFFFF',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  transition: 'all 0.10s ease',
                }}
              >
                {isSelected && (
                  <svg width="9" height="7" viewBox="0 0 9 7" fill="none">
                    <path
                      d="M1 3.5L3.5 6L8 1"
                      stroke="white"
                      strokeWidth="1.6"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                )}
              </span>
              <input
                type="checkbox"
                checked={isSelected}
                onChange={() => toggle(option)}
                style={{ display: 'none' }}
              />
              <span
                style={{
                  fontSize: 12.5,
                  color: isSelected ? BLUE : '#2a2a2a',
                  fontWeight: isSelected ? 600 : 400,
                  letterSpacing: '-0.01em',
                  lineHeight: 1.3,
                  flex: 1,
                  whiteSpace: 'nowrap',
                  overflow: 'hidden',
                  textOverflow: 'ellipsis',
                }}
              >
                {option}
              </span>
            </label>
          );
        })}
      </div>

      {/* ── Selection count footer ── */}
      {hasSelection && (
        <div
          style={{
            padding: '5px 12px',
            borderTop: '1px solid rgba(0,159,227,0.10)',
            backgroundColor: 'rgba(0,159,227,0.04)',
            flexShrink: 0,
            display: 'flex',
            alignItems: 'center',
            gap: 5,
          }}
        >
          <svg width="10" height="10" viewBox="0 0 24 24" fill={BLUE}>
            <circle cx="12" cy="12" r="10" />
            <path
              d="M8 12l3 3 5-6"
              stroke="white"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              fill="none"
            />
          </svg>
          <span style={{ fontSize: 11, color: BLUE, fontWeight: 600 }}>
            {selected.length} of {filter.options.length} selected
          </span>
        </div>
      )}
    </div>
  );
}

// ─── Filter bar ───────────────────────────────────────────────────────────────

export default function FilterBar({
  filters,
  selected,
  onSelectionChange,
  onClearAll,
  loading = false,
}: FilterBarProps) {
  const totalSelected = Object.values(selected).reduce(
    (sum, v) => sum + v.length,
    0
  );

  return (
    <div
      style={{
        padding: '0 2.5rem 1.25rem',
        borderBottom: '1px solid rgba(0,0,0,0.06)',
        marginBottom: '1rem',
      }}
    >
      {/* ── Bar header ── */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          marginBottom: 10,
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <svg
            width="13"
            height="13"
            viewBox="0 0 24 24"
            fill="none"
            stroke={NAVY}
            strokeWidth="2.2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3" />
          </svg>
          <span
            style={{
              fontSize: 12,
              fontWeight: 700,
              color: NAVY,
              letterSpacing: '-0.01em',
            }}
          >
            Filters
          </span>
          {totalSelected > 0 && (
            <span
              style={{
                fontSize: 10,
                fontWeight: 700,
                backgroundColor: BLUE,
                color: '#FFFFFF',
                borderRadius: 10,
                padding: '1px 7px',
                letterSpacing: '0.02em',
              }}
            >
              {totalSelected} active
            </span>
          )}
          {loading && (
            <span style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: 10, color: 'rgba(0,0,0,0.35)', fontWeight: 500 }}>
              <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke={BLUE} strokeWidth="2.5" strokeLinecap="round" style={{ animation: 'ts-spin 0.8s linear infinite' }}>
                <path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83" />
              </svg>
              Loading values…
              <style>{`@keyframes ts-spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }`}</style>
            </span>
          )}
        </div>

        {totalSelected > 0 && (
          <button
            type="button"
            onClick={onClearAll}
            style={{
              background: 'none',
              border: 'none',
              cursor: 'pointer',
              fontSize: 12,
              color: 'rgba(0,0,0,0.40)',
              fontWeight: 500,
              padding: 0,
              letterSpacing: '-0.01em',
            }}
          >
            Clear all filters
          </button>
        )}
      </div>

      {/* ── Horizontally scrollable card row ── */}
      <div
        style={{
          display: 'flex',
          gap: 10,
          overflowX: 'auto',
          paddingBottom: 6,
          /* Custom scrollbar */
          scrollbarWidth: 'thin',
          scrollbarColor: `rgba(0,159,227,0.25) transparent`,
        }}
      >
        {filters.map((f) => (
          <FilterCard
            key={f.id}
            filter={f}
            selected={selected[f.id] ?? []}
            onChange={(values) => onSelectionChange(f.id, values)}
          />
        ))}
      </div>
    </div>
  );
}
